using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using Newtonsoft.Json.Linq;
using UnityEditor;
using UnityEditor.U2D.Sprites;
using UnityEngine;
using Debug = UnityEngine.Debug;

// Space Station 14 uses RSI files. They are .zip files containing spritesheets and metadata.
// This script was generated by gpt 6 sol on a Hermes harness and is used specifically to consistently slice spritesheets.
public static class RsiPreview
{
    private const int CellSize = 32;
    private static readonly string[] FourDirections = { "south", "north", "east", "west" };

    [MenuItem("Tools/RSI/Preview Selected")]
    private static void PreviewSelected() => ProcessSelected(false);

    [MenuItem("Tools/RSI/Slice Selected")]
    private static void SliceSelected() => ProcessSelected(true);

    private static void ProcessSelected(bool apply)
    {
        if (!(Selection.activeObject is Texture2D texture))
        {
            Debug.LogError("Select the PNG texture asset (not a sliced child sprite) in the Project window.");
            return;
        }

        string assetPath = AssetDatabase.GetAssetPath(texture);
        if (!assetPath.StartsWith("Assets/Sprites/SS14/", StringComparison.Ordinal))
        {
            Debug.LogError("This tool only handles PNGs under Assets/Sprites/SS14/.");
            return;
        }

        string metadataPath = Path.Combine(Path.GetDirectoryName(assetPath), "source-meta.json");
        TextAsset metadataAsset = AssetDatabase.LoadAssetAtPath<TextAsset>(metadataPath);
        if (metadataAsset == null)
        {
            Debug.LogError($"No source-meta.json next to {assetPath}. Single hull tiles do not need slicing.");
            return;
        }

        try
        {
            JObject metadata = JObject.Parse(metadataAsset.text);
            int frameWidth = metadata["size"]?["x"]?.Value<int>() ?? 0;
            int frameHeight = metadata["size"]?["y"]?.Value<int>() ?? 0;
            if (frameWidth != CellSize || frameHeight != CellSize)
                throw new InvalidDataException($"Only 32x32 RSI frames are supported; metadata says {frameWidth}x{frameHeight}.");
            if (texture.width % CellSize != 0 || texture.height % CellSize != 0)
                throw new InvalidDataException($"PNG dimensions {texture.width}x{texture.height} are not multiples of 32.");

            string stateName = Path.GetFileNameWithoutExtension(assetPath);
            JArray states = metadata["states"] as JArray;
            JToken state = states?.FirstOrDefault(s => (string)s["name"] == stateName);
            if (state == null)
                throw new InvalidDataException($"State '{stateName}' is missing from {metadataPath}.");

            int directions = state["directions"]?.Value<int>() ?? 1;
            if (directions != 1 && directions != 4)
                throw new InvalidDataException($"State '{stateName}' has {directions} directions; only 1 or 4 are supported.");
            string[] names = directions == 4 ? FourDirections : new[] { "single" };
            JArray delays = state["delays"] as JArray;
            if (delays != null && delays.Count != directions)
                throw new InvalidDataException($"State '{stateName}' has {directions} directions but {delays.Count} delay groups.");

            var labels = new List<string>();
            for (int direction = 0; direction < directions; direction++)
            {
                int frames = delays == null ? 1 : (delays[direction] as JArray)?.Count ?? 0;
                if (frames < 1)
                    throw new InvalidDataException($"Direction {names[direction]} has no frames.");
                for (int frame = 0; frame < frames; frame++)
                    labels.Add($"{stateName}_{names[direction]}_{frame}");
            }

            int columns = texture.width / CellSize;
            int rows = texture.height / CellSize;
            if (labels.Count != columns * rows)
                throw new InvalidDataException($"Metadata expects {labels.Count} frames, PNG contains {columns * rows} cells.");

            var rects = new List<SpriteRect>();
            var report = new StringBuilder($"RSI {stateName}: {columns}x{rows} grid ({labels.Count} frames)\n");
            for (int i = 0; i < labels.Count; i++)
            {
                int column = i % columns;
                int rowFromTop = i / columns;
                var pixelRect = new Rect(column * CellSize, texture.height - (rowFromTop + 1) * CellSize,
                    CellSize, CellSize);
                rects.Add(new SpriteRect
                {
                    name = labels[i],
                    spriteID = GUID.Generate(),
                    rect = pixelRect,
                    alignment = SpriteAlignment.Center,
                    pivot = new Vector2(0.5f, 0.5f)
                });
                report.AppendLine($"{labels[i]}: {pixelRect}");
            }

            if (!apply)
            {
                Debug.Log(report.ToString());
                return;
            }

            var importer = AssetImporter.GetAtPath(assetPath) as TextureImporter;
            if (importer == null)
                throw new InvalidDataException($"No TextureImporter for {assetPath}.");

            var factory = new SpriteDataProviderFactories();
            factory.Init();
            var provider = factory.GetSpriteEditorDataProviderFromObject(importer);
            if (provider == null)
                throw new InvalidDataException("Sprite Editor data provider is unavailable.");
            provider.InitSpriteEditorDataProvider();
            var nameProvider = provider.GetDataProvider<ISpriteNameFileIdDataProvider>();
            if (nameProvider == null)
                throw new InvalidDataException("Sprite name/FileID provider is unavailable.");

            // Retain old IDs by cell order when the sheet was already sliced, preserving references.
            SpriteRect[] previous = provider.GetSpriteRects()
                .OrderByDescending(r => r.rect.y).ThenBy(r => r.rect.x).ToArray();
            if (previous.Length == rects.Count)
            {
                for (int i = 0; i < rects.Count; i++)
                    rects[i].spriteID = previous[i].spriteID;
            }
            else if (importer.spriteImportMode == SpriteImportMode.Multiple && previous.Length > 0)
            {
                throw new InvalidDataException($"Existing sheet has {previous.Length} sprites but metadata expects {rects.Count}. " +
                    "Refusing to replace them because existing references could break.");
            }

            importer.textureType = TextureImporterType.Sprite;
            importer.spriteImportMode = SpriteImportMode.Multiple;
            importer.spritePixelsPerUnit = CellSize;
            importer.filterMode = FilterMode.Point;
            importer.textureCompression = TextureImporterCompression.Uncompressed;
            importer.mipmapEnabled = false;
            provider.SetSpriteRects(rects.ToArray());
            nameProvider.SetNameFileIdPairs(rects.Select(r => new SpriteNameFileIdPair(r.name, r.spriteID)).ToArray());
            provider.Apply();
            importer.SaveAndReimport();
            Debug.Log($"Sliced {assetPath}: {rects.Count} named 32x32 sprites.\n{report}");
        }
        catch (Exception ex)
        {
            Debug.LogError($"RSI {assetPath}: {ex.Message}");
        }
    }
}
